$q=$pdo->prepare('SELECT * FROM mdm_grant_settings WHERE school_id=? ORDER BY effective_from DESC');$q->execute([$sid]);$rows=$q->fetchAll();mdm_layout_start('अनुदान सेटिंग — पोषण आहार');
?>
